using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
namespace Synkoz {
 static class InsertEffectR15 {
  internal static GraphNode15 Insert(TrackFx936 fx,GraphWire15 wire,EffectKind936 kind,Point point,out Action undo){if(!fx.Graph15.Wires.Contains(wire)||(wire.Port!=GraphPort15.Video&&wire.Port!=GraphPort15.VideoB)||kind==EffectKind936.Texte||kind==EffectKind936.Animation)throw new InvalidOperationException("Insérer un effet visuel nécessite un câble vidéo.");var before=fx.Graph15.Nodes.Single(n=>n.Id==wire.From);var after=fx.Graph15.Nodes.Single(n=>n.Id==wire.To);var mixerBefore=after.MixerR20==null?null:UiR2.Copy(after.MixerR20);var inherit=fx.Graph15.Wires.Any(w=>w.To==before.Id&&w.Port==GraphPort15.Trigger)?before:after;var effect=new Effect936{Kind=kind,Release=0,Length=Length936.Noire};var node=new GraphNode15{Kind=GraphKind15.Effect,EffectId=effect.IdR8,X=point.X,Y=point.Y,ActivationR4=UiR2.Copy(inherit.ActivationR4),ThresholdR4=inherit.ThresholdR4,TriggerLevelR4=inherit.TriggerLevelR4,RearmR4=inherit.RearmR4};var links=new List<GraphWire15>{new GraphWire15{From=wire.From,To=node.Id,Port=GraphPort15.Video,Order=wire.Order},new GraphWire15{From=node.Id,To=wire.To,Port=wire.Port,Order=wire.Order}};links.AddRange(fx.Graph15.Wires.Where(w=>w.To==inherit.Id&&w.Port==GraphPort15.Trigger).Select(w=>new GraphWire15{From=w.From,To=node.Id,Port=w.Port,Order=w.Order}));fx.Graph15.Wires.Remove(wire);fx.Graph15.Nodes.Add(node);fx.Effects.Add(effect);fx.Graph15.Wires.AddRange(links);if(after.MixerR20!=null)foreach(var row in after.MixerR20.Sources.Where(x=>x.Node==wire.From))row.Node=node.Id;Action revert=()=>{after.MixerR20=mixerBefore;fx.Graph15.Wires.RemoveAll(w=>w.From==node.Id||w.To==node.Id);fx.Graph15.Nodes.Remove(node);fx.Effects.Remove(effect);if(!fx.Graph15.Wires.Any(w=>w.From==wire.From&&w.To==wire.To&&w.Port==wire.Port))fx.Graph15.Wires.Add(wire);};try{GraphRules15.Validate(fx);}catch{revert();throw;}undo=revert;return node;}
 }
 internal sealed partial class GraphCanvas15 {
  void InsertMenuR15(ContextMenuStrip menu,GraphWire15 wire,Point point){var root=new ToolStripMenuItem("Insérer un effet");if(wire.Port!=GraphPort15.Video&&wire.Port!=GraphPort15.VideoB){root.Enabled=false;root.ToolTipText="Les effets visuels se placent sur les câbles vidéo.";menu.Items.Add(root);return;}for(int group=0;group<CategoriesA01.Names.Length;group++){int category=group;var branch=new ToolStripMenuItem(CategoriesA01.Names[group]);foreach(var kind in Enum.GetValues(typeof(EffectKind936)).Cast<EffectKind936>().Where(k=>k!=EffectKind936.Texte&&k!=EffectKind936.Animation&&CategoriesA01.Group(k)==category)){var chosen=kind;branch.DropDownItems.Add(kind.ToString().Replace('_',' '),null,delegate{try{Action undoInsertion;selected=InsertEffectR15.Insert(fx,wire,chosen,point,out undoInsertion);selectedWire=null;Invalidate();if(Changed!=null)Changed();}catch(Exception ex){if(Error!=null)Error(ex.Message);}});}root.DropDownItems.Add(branch);}menu.Items.Add(root);}
 }
}
